def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    minority = min(counts, key=counts.get)
    points = sorted((r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == minority)

    def cross(o, a, b):
        return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

    if len(points) <= 1:
        hull = points
    else:
        lower = []
        for p in points:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)
        upper = []
        for p in reversed(points):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)
        hull = lower[:-1] + upper[:-1]

    out = [row[:] for row in grid]
    if len(hull) == 1:
        return out
    if len(hull) == 2:
        a, b = hull
        for r in range(h):
            for c in range(w):
                if cross(a, b, (r,c)) == 0 and min(a[0],b[0]) <= r <= max(a[0],b[0]) and min(a[1],b[1]) <= c <= max(a[1],b[1]) and grid[r][c] != minority:
                    out[r][c] = 3
        return out
    for r in range(h):
        for c in range(w):
            if grid[r][c] == minority:
                continue
            signs = [cross(hull[i], hull[(i+1) % len(hull)], (r,c)) for i in range(len(hull))]
            if all(x >= 0 for x in signs) or all(x <= 0 for x in signs):
                out[r][c] = 3
    return out
